The current implementation of `has_pull_request_trigger` scans all indented lines under the `on:` block. This can lead to false positives if the word `pull_request` is used in nested fields that are not event triggers, such as descriptions or input names under `workflow_dispatch` (e.g., `inputs.pr_number.description: "The pull_request number"`).

To prevent these false positives, we can track the indentation level of the first child under `on:` and only evaluate lines that match this top-level event indentation.

```python
def has_pull_request_trigger(lines: Sequence[tuple[int, str]]) -> bool:
    for index, (_, line) in enumerate(lines):
        if not line.strip() or indent_width(line) != 0:
            continue

        match = re.match(r"on\s*:\s*(.*)$", line)
        if not match:
            continue

        if contains_pull_request_event(match.group(1)):
            return True

        first_child_indent = None
        for _, child_line in lines[index + 1 :]:
            if not child_line.strip():
                continue
            if indent_width(child_line) == 0:
                break

            if first_child_indent is None:
                first_child_indent = indent_width(child_line)

            if indent_width(child_line) == first_child_indent:
                stripped = child_line.strip()
                if contains_pull_request_event(stripped):
                    return True
        return False

    return False
```
